DELETE FROM sd_blog_article_version WHERE version_id    >= 2240000000000000000 AND version_id      < 2250000000000000000;
DELETE FROM sd_blog_article       WHERE article_id      >= 2230000000000000000 AND article_id      < 2240000000000000000;
DELETE FROM sd_blog_tag_alias     WHERE tag_id          >= 2220000000000000000 AND tag_id          < 2230000000000000000;
DELETE FROM sd_blog_tag           WHERE tag_id          >= 2220000000000000000 AND tag_id          < 2230000000000000000;
DELETE FROM sd_blog_user_profile  WHERE user_id         >= 2210000000000000000 AND user_id         < 2220000000000000000;
DELETE FROM sys_user_role         WHERE user_id         >= 2210000000000000000 AND user_id         < 2220000000000000000;
DELETE FROM sys_user              WHERE user_id         >= 2210000000000000000 AND user_id         < 2220000000000000000;

-- 顶掉同名的旧标签（slug 唯一键冲突），连同它们的文章关系一并清理
DELETE FROM sd_blog_article_tag WHERE tag_id IN (SELECT tag_id FROM (SELECT tag_id FROM sd_blog_tag WHERE name IN ('Java', 'Spring Boot', 'MySQL', 'Redis', 'Vue', 'TypeScript', 'Docker', 'Elasticsearch', 'JVM', '性能优化') AND tag_id < 2220000000000000000) t);
DELETE FROM sd_blog_tag_alias  WHERE tag_id IN (SELECT tag_id FROM (SELECT tag_id FROM sd_blog_tag WHERE name IN ('Java', 'Spring Boot', 'MySQL', 'Redis', 'Vue', 'TypeScript', 'Docker', 'Elasticsearch', 'JVM', '性能优化') AND tag_id < 2220000000000000000) u);
DELETE FROM sd_blog_tag        WHERE name IN ('Java', 'Spring Boot', 'MySQL', 'Redis', 'Vue', 'TypeScript', 'Docker', 'Elasticsearch', 'JVM', '性能优化') AND tag_id < 2220000000000000000;

