INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000001, 2210000000000000001, NULL, '1', '0', 2240000000000000001, 5120, '2026-08-06 09:00:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000001, '2026-08-06 06:00:00', 2210000000000000001, '2026-08-06 06:00:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000001, 2230000000000000001, 1, 'Spring Boot 自动配置到底是怎么生效的', '从 @SpringBootApplication 拆到 AutoConfigurationImportSelector，再追到 spring.factories 与 AutoConfiguration.imports，把「引入依赖就能用」这件事讲透。', 'https://img.sdblog.us.ci/ruoyi/seed/covers/c01.svg', '<h2>一个让人困惑的现象</h2><p>加上 <code>spring-boot-starter-web</code> 依赖，什么都没配，Tomcat 就起来了、Jackson 就注册好了。这套「约定优于配置」的魔法入口，其实只有三个环节。</p><h2>第一环：@SpringBootApplication 是三个注解的合成</h2><p>它等价于 <code>@SpringBootConfiguration</code>、<code>@EnableAutoConfiguration</code>、<code>@ComponentScan</code>。真正干活的是中间那个。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c01.svg" alt="Spring Boot 自动配置到底是怎么生效的 · 示意图一" loading="lazy"><figcaption>Spring Boot 自动配置到底是怎么生效的 · 示意图一</figcaption></figure><pre><code class="language-java"><span class="tok-140thh">@</span><span class="tok-1itgoe">SpringBootApplication</span>
<span class="tok-1itgoe">public</span><span class="tok-1itgoe"> class</span><span class="tok-1t8gfj"> Application</span><span class="tok-140thh"> {</span>
<span class="tok-1itgoe">    public</span><span class="tok-1itgoe"> static</span><span class="tok-1itgoe"> void</span><span class="tok-1t8gfj"> main</span><span class="tok-140thh">(</span><span class="tok-1itgoe">String</span><span class="tok-140thh">[] </span><span class="tok-1jdh33">args</span><span class="tok-140thh">) {</span>
<span class="tok-140thh">        SpringApplication.</span><span class="tok-1t8gfj">run</span><span class="tok-140thh">(Application.class, args);</span>
<span class="tok-140thh">    }</span>
<span class="tok-140thh">}</span></code></pre><h2>第二环：@EnableAutoConfiguration 导入选择器</h2><p>它通过 <code>@Import(AutoConfigurationImportSelector.class)</code> 把「候选配置类清单」交给容器。选择器不写死清单，而是去读 classpath 下的元数据文件。</p><h2>第三环：元数据文件里的候选清单</h2><p>Spring Boot 2.7 之前是 <code>META-INF/spring.factories</code>，之后迁到 <code>META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports</code>，一行一个全限定类名。</p><blockquote><p>所以「引入依赖就能用」的本质是：依赖里带了元数据文件，文件里列了配置类，配置类上带条件注解。</p></blockquote><h2>条件注解才是真正的守门人</h2><p><code>@ConditionalOnClass</code>、<code>@ConditionalOnMissingBean</code> 这些决定了配置类会不会生效。排查「为什么我的自动配置没生效」时，打开 <code>--debug</code> 看 condition evaluation report 比读源码快得多。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c04.svg" alt="Spring Boot 自动配置到底是怎么生效的 · 示意图二" loading="lazy"><figcaption>Spring Boot 自动配置到底是怎么生效的 · 示意图二</figcaption></figure><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p>', 1761000000000000103, 2210000000000000001, '2026-08-06 06:00:00', 2210000000000000001, '2026-08-06 06:00:00', '0');
