INSERT INTO sd_blog_article_tag (article_tag_id, article_id, tag_id, create_dept, create_by, create_time, update_by, update_time) VALUES (2260000000000000004, 2230000000000000002, 2220000000000000017, 1761000000000000103, 2210000000000000002, '2026-08-18 07:07:00', 2210000000000000002, '2026-08-18 07:07:00');
INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000003, 2210000000000000001, NULL, '1', '0', 2240000000000000003, 3960, '2026-08-31 11:14:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000001, '2026-08-31 08:14:00', 2210000000000000001, '2026-08-31 08:14:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000003, 2230000000000000003, 1, 'Redis 缓存穿透、击穿、雪崩：三种病与三张药方', '名字很像，成因完全不同。把三者拆开讲清楚，再分别给布隆过滤器、互斥锁、过期时间打散的具体做法。', 'https://img.sdblog.us.ci/ruoyi/seed/covers/c03.svg', '<h2>三种故障的差别</h2><ul><li><strong>穿透</strong>：查一个数据库里也不存在的 key，缓存永远不命中</li><li><strong>击穿</strong>：某个热点 key 恰好过期，瞬间请求全打到数据库</li><li><strong>雪崩</strong>：大批 key 同一时刻过期，或 Redis 整体不可用</li></ul><h2>穿透：先挡掉不可能的请求</h2><p>布隆过滤器能判断「这个 key 一定不存在」，把无效请求挡在缓存层之前。代价是存在极小的误判率，且不支持删除。</p><pre><code class="language-java"><span class="tok-1itgoe">if</span><span class="tok-140thh"> (</span><span class="tok-1itgoe">!</span><span class="tok-140thh">bloomFilter.</span><span class="tok-1t8gfj">mightContain</span><span class="tok-140thh">(key)) {</span>
<span class="tok-1itgoe">    return</span><span class="tok-dzsirb"> null</span><span class="tok-140thh">;   </span><span class="tok-21nrsd">// 一定不存在，不查缓存也不查库</span>
<span class="tok-140thh">}</span>
<span class="tok-140thh">Object cached </span><span class="tok-1itgoe">=</span><span class="tok-140thh"> redis.</span><span class="tok-1t8gfj">get</span><span class="tok-140thh">(key);</span>
<span class="tok-1itgoe">if</span><span class="tok-140thh"> (cached </span><span class="tok-1itgoe">!=</span><span class="tok-dzsirb"> null</span><span class="tok-140thh">) {</span>
<span class="tok-1itgoe">    return</span><span class="tok-140thh"> cached;</span>
<span class="tok-140thh">}</span>
<span class="tok-21nrsd">// 回源，即使查不到也缓存空值（短 TTL）</span>
<span class="tok-140thh">Object dbValue </span><span class="tok-1itgoe">=</span><span class="tok-140thh"> repository.</span><span class="tok-1t8gfj">findById</span><span class="tok-140thh">(key);</span>
<span class="tok-140thh">redis.</span><span class="tok-1t8gfj">set</span><span class="tok-140thh">(key, dbValue </span><span class="tok-1itgoe">==</span><span class="tok-dzsirb"> null</span><span class="tok-1itgoe"> ?</span><span class="tok-140thh"> EMPTY </span><span class="tok-1itgoe">:</span><span class="tok-140thh"> dbValue, </span><span class="tok-dzsirb">60</span><span class="tok-140thh">, TimeUnit.SECONDS);</span></code></pre><h2>击穿：让一个请求去回源</h2><p>对同一个 key 加互斥锁，只有一个线程回源，其余等待。注意锁要设超时，否则回源失败会一直阻塞。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c03.svg" alt="Redis 缓存穿透、击穿、雪崩：三种病与三张药方 · 示意图一" loading="lazy"><figcaption>Redis 缓存穿透、击穿、雪崩：三种病与三张药方 · 示意图一</figcaption></figure><h2>雪崩：把过期时间打散</h2><p>在基础 TTL 上加一个随机偏移，避免批量 key 同时失效。Redis 整体不可用则要靠降级（限流 + 本地缓存兜底），不是缓存层能解决的。</p><blockquote><p>这三种问题的共同点是「缓存没帮上忙」。判断属于哪一种，看的是「没命中的原因」，而不是现象像不像。</p></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c06.svg" alt="Redis 缓存穿透、击穿、雪崩：三种病与三张药方 · 示意图二" loading="lazy"><figcaption>Redis 缓存穿透、击穿、雪崩：三种病与三张药方 · 示意图二</figcaption></figure><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
<span class="tok-140thh">explain </span><span class="tok-1itgoe">select</span><span class="tok-140thh"> article_id, title</span>
<span class="tok-1itgoe">  from</span><span class="tok-140thh"> sd_blog_article</span>
<span class="tok-1itgoe"> where</span><span class="tok-1itgoe"> status</span><span class="tok-1itgoe"> =</span><span class="tok-mdbnqw"> ''1''</span>
<span class="tok-1itgoe"> order by</span><span class="tok-140thh"> published_at </span><span class="tok-1itgoe">desc</span>
<span class="tok-1itgoe"> limit</span><span class="tok-dzsirb"> 20</span><span class="tok-140thh">;</span></code></pre><p>执行计划里出现 filesort 就说明排序没有走索引；补一个联合索引后再看，type 从 ALL 变成 range，排序消失。</p><blockquote><p>先用五分钟证伪，胜过用五小时论证。</p></blockquote><p>这套"最小实验"的习惯，最大的收益不是省时间，而是让讨论从"我觉得"变成"跑出来是这样"。</p>', 1761000000000000103, 2210000000000000001, '2026-08-31 08:14:00', 2210000000000000001, '2026-08-31 08:14:00', '0');
