INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000004, 2210000000000000003, NULL, '1', '0', 2240000000000000004, 3410, '2026-09-13 12:21:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000003, '2026-09-13 09:21:00', 2210000000000000003, '2026-09-13 09:21:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000004, 2230000000000000004, 1, 'Vue 3 响应式系统拆解：Proxy 与依赖收集', '从 reactive() 到 effect()，把 track 与 trigger 两个过程走一遍，解释为什么 Vue 3 能精确到属性级别触发更新。', 'https://img.sdblog.us.ci/ruoyi/seed/covers/c04.svg', '<h2>Vue 2 的 Object.defineProperty 撞到了什么墙</h2><p>它只能劫持已存在的属性：新增属性要 <code>$set</code>，数组方法要重写，深层对象要递归遍历。Vue 3 换成 Proxy 后，这三个问题一起消失。</p><pre><code class="language-javascript"><span class="tok-1itgoe">const</span><span class="tok-dzsirb"> state</span><span class="tok-1itgoe"> =</span><span class="tok-1t8gfj"> reactive</span><span class="tok-140thh">({ count: </span><span class="tok-dzsirb">0</span><span class="tok-140thh"> });</span>

<span class="tok-1t8gfj">effect</span><span class="tok-140thh">(() </span><span class="tok-1itgoe">=></span><span class="tok-140thh"> {</span>
<span class="tok-140thh">  console.</span><span class="tok-1t8gfj">log</span><span class="tok-140thh">(state.count);   </span><span class="tok-21nrsd">// 读取时 track</span>
<span class="tok-140thh">});</span>

<span class="tok-140thh">state.count</span><span class="tok-1itgoe">++</span><span class="tok-140thh">;                 </span><span class="tok-21nrsd">// 写入时 trigger</span></code></pre><h2>依赖收集的容器长什么样</h2><p>核心是三层 Map：<code>targetMap: WeakMap&lt;target, Map&lt;key, Set&lt;effect&gt;&gt;&gt;</code>。一个对象对应一组 key，一个 key 对应一组副作用函数。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c04.svg" alt="Vue 3 响应式系统拆解：Proxy 与依赖收集 · 示意图一" loading="lazy"><figcaption>Vue 3 响应式系统拆解：Proxy 与依赖收集 · 示意图一</figcaption></figure><h2>为什么要用 WeakMap</h2><p>键是对象，弱引用意味着对象被回收时对应的依赖表自动释放，不需要手动清理，也不会阻止垃圾回收。</p><h2>computed 是惰性的 effect</h2><p>它把自己的 getter 包成 effect，但加了 <code>dirty</code> 标记：依赖变化时只置脏不重算，真正读取时才求值。这就是「计算属性不会立即执行」的原因。</p><h2>如果重来一次，我会怎么改</h2><p>回头看，这件事本可以在半天内做完，实际花了两天。差别不在技术难度，而在动手前的十分钟：先写清楚验收标准，再写代码。</p><ul><li>先把"完成"定义成可验证的观测指标，而不是"功能跑通"</li><li>先做最小闭环（能跑通一条链路），再补齐异常分支</li><li>把回归手段前置：能一条命令复现的问题，改起来才敢下手</li></ul><p>顺序一换，很多"改到一半发现方向不对"的返工就不会发生。技术方案的价值，往往体现在它让后续每一次修改都更便宜。</p><blockquote><p>写代码的时间只占三分之一，剩下的是让它可被验证、可被回滚、可被接手。</p></blockquote><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p>', 1761000000000000103, 2210000000000000003, '2026-09-13 09:21:00', 2210000000000000003, '2026-09-13 09:21:00', '0');
INSERT INTO sd_blog_article_tag (article_tag_id, article_id, tag_id, create_dept, create_by, create_time, update_by, update_time) VALUES (2260000000000000008, 2230000000000000004, 2220000000000000005, 1761000000000000103, 2210000000000000003, '2026-09-13 09:21:00', 2210000000000000003, '2026-09-13 09:21:00');
