INSERT INTO sd_blog_article_tag (article_tag_id, article_id, tag_id, create_dept, create_by, create_time, update_by, update_time) VALUES (2260000000000000011, 2230000000000000005, 2220000000000000010, 1761000000000000103, 2210000000000000004, '2026-09-28 10:28:00', 2210000000000000004, '2026-09-28 10:28:00');
INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000006, 2210000000000000001, NULL, '0', '0', 2240000000000000006, 0, NULL, NULL, NULL, NULL, 1761000000000000103, 2210000000000000001, '2026-10-19 09:00:00', 2210000000000000001, '2026-10-19 09:00:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000006, 2230000000000000006, 1, '还在改的方案：把博客搜索从 LIKE 换成 ES', '一篇没写完的草稿，记录思路：为什么 LIKE 撑不住、IK 分词怎么配、以及降级到 MySQL 的兜底该怎么写。', 'https://img.sdblog.us.ci/ruoyi/seed/covers/c06.svg', '<h2>为什么 LIKE 不够用</h2><p><code>LIKE ''%关键词%''</code> 无法用索引，数据量一上来就是全表扫描；而且中文没有空格分词，搜「缓存穿透」匹配不到「缓存击穿」。</p><h2>待验证的点</h2><ul><li>IK 分词器的词典要不要加技术术语（如 Vue、Redis 这类英文词的大小写归一）</li><li>索引 mapping 里 summary 与 content 的权重怎么分</li><li>ES 挂了之后降级到 LIKE 的切换阈值</li></ul><p><em>（草稿：还没跑压测数据，暂不发布。）</em></p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c06.svg" alt="还在改的方案：把博客搜索从 LIKE 换成 ES · 示意图一" loading="lazy"><figcaption>还在改的方案：把博客搜索从 LIKE 换成 ES · 示意图一</figcaption></figure><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p>', 1761000000000000103, 2210000000000000001, '2026-10-19 09:00:00', 2210000000000000001, '2026-10-19 09:00:00', '0');
