INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000007, 2210000000000000003, NULL, '1', '1', 2240000000000000007, 840, '2026-10-11 15:42:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000003, '2026-10-11 12:42:00', 2210000000000000003, '2026-10-11 12:42:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000007, 2230000000000000007, 1, '我把自己的博客下线了一天', '一次「主动下线」的复盘：为什么隐藏文章、隐藏和删除的区别、以及读者视角下应该看到什么。', 'https://img.sdblog.us.ci/ruoyi/seed/covers/c06.svg', '<h2>起因</h2><p>有篇文章里的示例代码在生产环境跑出了事故，虽然文章本身没错，但我不想在没补充警告前让它继续传播。</p><h2>隐藏不是删除</h2><p>隐藏后文章还在、版本还在、链接会 404 但数据完整；删除是逻辑删除，作者自己也看不到了。前者可逆，后者要找回很麻烦。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c07.svg" alt="我把自己的博客下线了一天 · 示意图一" loading="lazy"><figcaption>我把自己的博客下线了一天 · 示意图一</figcaption></figure><blockquote><p>内容平台的「下线」应该是可逆操作，且必须记录原因与操作人——这次我给自己补上了这条。</p></blockquote><h2>读者看到什么</h2><p>列表里消失，直达链接提示已下线。不显示「作者删除了」这类容易误解的文案。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c10.svg" alt="我把自己的博客下线了一天 · 示意图二" loading="lazy"><figcaption>我把自己的博客下线了一天 · 示意图二</figcaption></figure><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
<span class="tok-1itgoe">for</span><span class="tok-140thh"> h </span><span class="tok-1itgoe">in</span><span class="tok-mdbnqw"> app-01</span><span class="tok-mdbnqw"> app-02</span><span class="tok-mdbnqw"> app-03</span><span class="tok-140thh">; </span><span class="tok-1itgoe">do</span>
<span class="tok-dzsirb">  echo</span><span class="tok-dzsirb"> -n</span><span class="tok-mdbnqw"> "</span><span class="tok-140thh">$h</span><span class="tok-mdbnqw"> "</span>
<span class="tok-1t8gfj">  curl</span><span class="tok-dzsirb"> -s</span><span class="tok-mdbnqw"> "http://</span><span class="tok-140thh">$h</span><span class="tok-mdbnqw">:9090/metrics"</span><span class="tok-1itgoe"> |</span><span class="tok-1t8gfj"> grep</span><span class="tok-mdbnqw"> http_request_duration_p99</span>
<span class="tok-1itgoe">done</span>

<span class="tok-21nrsd"># 2) 再确认是不是下游</span>
<span class="tok-1itgoe">time</span><span class="tok-140thh"> curl -s -o /dev/null http://127.0.0.1:8081/healthz</span></code></pre><p>结果三台机器的 P99 同步抬升，说明不是单实例的 JIT 或 GC 问题；再往下看依赖，发现是连接池在高并发下反复建连。把连接复用和超时对齐之后，长尾立刻收敛。</p><ul><li>平均值正常但长尾异常，优先怀疑锁、连接池、GC</li><li>先排除"单实例"，再排除"下游"，最后才看自己的代码</li><li>每次排查都留一条可复用的命令，下次十分钟内能复现同一视角</li></ul><h2>如果重来一次，我会怎么改</h2><p>回头看，这件事本可以在半天内做完，实际花了两天。差别不在技术难度，而在动手前的十分钟：先写清楚验收标准，再写代码。</p><ul><li>先把"完成"定义成可验证的观测指标，而不是"功能跑通"</li><li>先做最小闭环（能跑通一条链路），再补齐异常分支</li><li>把回归手段前置：能一条命令复现的问题，改起来才敢下手</li></ul><p>顺序一换，很多"改到一半发现方向不对"的返工就不会发生。技术方案的价值，往往体现在它让后续每一次修改都更便宜。</p><blockquote><p>写代码的时间只占三分之一，剩下的是让它可被验证、可被回滚、可被接手。</p></blockquote>', 1761000000000000103, 2210000000000000003, '2026-10-11 12:42:00', 2210000000000000003, '2026-10-11 12:42:00', '0');
INSERT INTO sd_blog_article_tag (article_tag_id, article_id, tag_id, create_dept, create_by, create_time, update_by, update_time) VALUES (2260000000000000013, 2230000000000000007, 2220000000000000011, 1761000000000000103, 2210000000000000003, '2026-10-11 12:42:00', 2210000000000000003, '2026-10-11 12:42:00');
INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000008, 2210000000000000002, NULL, '1', '2', 2240000000000000008, 1560, '2026-10-22 16:49:00', '示例代码在高并发场景下可能造成死锁，需作者补充前置条件说明后重新发布', 1761100000000000001, '2026-10-24 15:30:00', 1761000000000000103, 2210000000000000002, '2026-10-22 13:49:00', 2210000000000000002, '2026-10-22 13:49:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000008, 2230000000000000008, 1, '（已下线）一段被误用的并发示例代码', '这篇文章里的示例在特定场景下会死锁，已由管理员下线，等待作者修订。', 'https://img.sdblog.us.ci/ruoyi/seed/covers/c08.svg', '<h2>示例代码（已标记风险）</h2><pre><code class="language-java"><span class="tok-1itgoe">synchronized</span><span class="tok-140thh"> (a) {</span>
<span class="tok-21nrsd">    // 这里如果另一个线程持有 b 再去拿 a，就会死锁</span>
<span class="tok-1itgoe">    synchronized</span><span class="tok-140thh"> (b) {</span>
<span class="tok-21nrsd">        // ...</span>
<span class="tok-140thh">    }</span>
<span class="tok-140thh">}</span></code></pre><p>本文已被管理员下线。示例缺少「加锁顺序一致性」的前置说明，直接照抄有风险。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/seed/covers/c08.svg" alt="（已下线）一段被误用的并发示例代码 · 示意图一" loading="lazy"><figcaption>（已下线）一段被误用的并发示例代码 · 示意图一</figcaption></figure><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
<span class="tok-140thh">explain </span><span class="tok-1itgoe">select</span><span class="tok-140thh"> article_id, title</span>
<span class="tok-1itgoe">  from</span><span class="tok-140thh"> sd_blog_article</span>
<span class="tok-1itgoe"> where</span><span class="tok-1itgoe"> status</span><span class="tok-1itgoe"> =</span><span class="tok-mdbnqw"> ''1''</span>
<span class="tok-1itgoe"> order by</span><span class="tok-140thh"> published_at </span><span class="tok-1itgoe">desc</span>
<span class="tok-1itgoe"> limit</span><span class="tok-dzsirb"> 20</span><span class="tok-140thh">;</span></code></pre><p>执行计划里出现 filesort 就说明排序没有走索引；补一个联合索引后再看，type 从 ALL 变成 range，排序消失。</p><blockquote><p>先用五分钟证伪，胜过用五小时论证。</p></blockquote><p>这套"最小实验"的习惯，最大的收益不是省时间，而是让讨论从"我觉得"变成"跑出来是这样"。</p>', 1761000000000000103, 2210000000000000002, '2026-10-22 13:49:00', 2210000000000000002, '2026-10-22 13:49:00', '0');
INSERT INTO sd_blog_article_tag (article_tag_id, article_id, tag_id, create_dept, create_by, create_time, update_by, update_time) VALUES (2260000000000000014, 2230000000000000008, 2220000000000000001, 1761000000000000103, 2210000000000000002, '2026-10-22 13:49:00', 2210000000000000002, '2026-10-22 13:49:00');
