-- ---------- 评论（只挂在已发布且公开的文章上；时间晚于文章发布）----------
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000001, 2230000000000000001, 2210000000000000002, NULL, '这篇的排查路径写得很清楚，尤其是先看 EXPLAIN 而不是直接加索引那段，吃过亏。', 1761000000000000103, 2210000000000000002, '2026-08-06 11:00:00', 2210000000000000002, '2026-08-06 11:00:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000002, 2230000000000000002, 2210000000000000004, NULL, '补充一点：我们线上也遇到过，最后定位到是统计信息过期，ANALYZE TABLE 之后就恢复了。', 1761000000000000103, 2210000000000000004, '2026-08-20 01:07:00', 2210000000000000004, '2026-08-20 01:07:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000003, 2230000000000000003, 2210000000000000001, NULL, '看完去翻了下我们的慢日志，确实有一条跟文里一模一样，回头就改。', 1761000000000000103, 2210000000000000001, '2026-09-03 15:14:00', 2210000000000000001, '2026-09-03 15:14:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000004, 2230000000000000004, 2210000000000000003, NULL, '「先确定 LCP 元素是什么，再决定砍什么」这句说到点子上了，之前优化方向一直是错的。', 1761000000000000103, 2210000000000000003, '2026-09-18 05:21:00', 2210000000000000003, '2026-09-18 05:21:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000005, 2230000000000000005, 2210000000000000005, NULL, '请问这个结论在不同版本上验证过吗？我们用的版本比较老，行为好像不太一样。', 1761000000000000103, 2210000000000000005, '2026-10-04 19:28:00', 2210000000000000005, '2026-10-04 19:28:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000006, 2230000000000000007, 2210000000000000003, NULL, '写得很克制，没有堆术语。收藏了。', 1761000000000000103, 2210000000000000003, '2026-10-19 10:42:00', 2210000000000000003, '2026-10-19 10:42:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000007, 2230000000000000001, 2210000000000000003, NULL, '第三点我持保留意见，理论上可行，但实际项目里改造成本比收益高。', 1761000000000000103, 2210000000000000003, '2026-08-15 17:00:00', 2210000000000000003, '2026-08-15 17:00:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000008, 2230000000000000002, 2210000000000000005, NULL, '正好在排查类似问题，按这个思路试了一下，确实定位到了。谢谢。', 1761000000000000103, 2210000000000000005, '2026-08-29 07:07:00', 2210000000000000005, '2026-08-29 07:07:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000009, 2230000000000000003, 2210000000000000002, NULL, '这个坑我也踩过，当时的解法更土一点，直接加机器绕过去了，现在知道根因了。', 1761000000000000103, 2210000000000000002, '2026-09-12 21:14:00', 2210000000000000002, '2026-09-12 21:14:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000010, 2230000000000000004, 2210000000000000004, NULL, '希望能再展开讲讲失败回滚那部分，这块一直没想清楚。', 1761000000000000103, 2210000000000000004, '2026-09-27 11:21:00', 2210000000000000004, '2026-09-27 11:21:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000011, 2230000000000000005, 2210000000000000001, NULL, '文里的示例代码可以直接跑，这点很难得。', 1761000000000000103, 2210000000000000001, '2026-10-14 01:28:00', 2210000000000000001, '2026-10-14 01:28:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000012, 2230000000000000007, 2210000000000000004, NULL, '对照着改了一版，指标确实有改善，不过幅度没有文里说的大，可能跟我们数据量有关。', 1761000000000000103, 2210000000000000004, '2026-10-28 16:42:00', 2210000000000000004, '2026-10-28 16:42:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000013, 2230000000000000001, 2210000000000000004, NULL, '有个细节想确认：这里说的超时是连接超时还是读取超时？两者表现差别挺大的。', 1761000000000000103, 2210000000000000004, '2026-08-24 23:00:00', 2210000000000000004, '2026-08-24 23:00:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000014, 2230000000000000002, 2210000000000000001, NULL, '看标题以为是水文，点进来发现是真踩过的，收藏。', 1761000000000000103, 2210000000000000001, '2026-08-18 13:07:00', 2210000000000000001, '2026-08-18 13:07:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000015, 2230000000000000003, 2210000000000000003, NULL, '「把个人偏好标成必须改是评审最常见的摩擦源」——这句值得贴在墙上。', 1761000000000000103, 2210000000000000003, '2026-09-02 03:14:00', 2210000000000000003, '2026-09-02 03:14:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000016, 2230000000000000004, 2210000000000000005, NULL, '之前一直以为这个问题只能靠加缓存解决，原来是索引的问题。', 1761000000000000103, 2210000000000000005, '2026-09-16 17:21:00', 2210000000000000005, '2026-09-16 17:21:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000017, 2230000000000000005, 2210000000000000002, NULL, '这类文章最有价值的地方是给了判断依据，而不是给了一个标准答案。', 1761000000000000103, 2210000000000000002, '2026-10-03 07:28:00', 2210000000000000002, '2026-10-03 07:28:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000018, 2230000000000000007, 2210000000000000005, NULL, '补充一个边界：并发很高的时候这个方案会退化成串行，要注意。', 1761000000000000103, 2210000000000000005, '2026-10-17 22:42:00', 2210000000000000005, '2026-10-17 22:42:00', '0');
