INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000020, 2230000000000000002, 2210000000000000002, NULL, '能不能出个续篇，讲讲线上灰度怎么配合这块？', 1761000000000000103, 2210000000000000002, '2026-08-27 19:07:00', 2210000000000000002, '2026-08-27 19:07:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000021, 2230000000000000003, 2210000000000000004, NULL, '这篇的排查路径写得很清楚，尤其是先看 EXPLAIN 而不是直接加索引那段，吃过亏。', 1761000000000000103, 2210000000000000004, '2026-09-11 09:14:00', 2210000000000000004, '2026-09-11 09:14:00', '0');
